  if (pm) permisoPlan[pil] = pm[1].trim();
}
return [{ json: { ok: true, valido: true, dry_run: dryRun, company_id: companyId, idioma, cantidad: cantidadFinal, formatosPlan, permisoPlan, pilares, productos: prods.map(p => p.name), ideas,
